const { Builder, By, until } = require('selenium-webdriver');

test('el comprador inicia sesión y ve su carrito', async () => {
  const driver = await new Builder().forBrowser('firefox').build();
  try {
    await driver.get('https://staging.qatu.com/login');
    await driver.findElement(By.id('email')).sendKeys('ana@qatu.com');
    await driver.findElement(By.id('password')).sendKeys(process.env.CLAVE_PRUEBA);
    await driver.findElement(By.css('button[type=submit]')).click();

    const contador = await driver.wait(
      until.elementLocated(By.css('[data-test=carrito-contador]')), 5000);
    expect(await contador.getText()).toBe('3');
  } finally {
    await driver.quit();
  }
});

